import sys

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    n = int(data)
    if n == 0:
        print("0")
        return
    bits = []
    while n > 0:
        bits.append(str(n % 2))
        n //= 2
    print(''.join(bits[::-1]))

if __name__ == "__main__":
    main()
